(function () {
  'use strict';

  // Load Three.js dynamically if not already loaded on the page
  function loadThree(callback) {
    if (window.THREE) {
      callback(window.THREE);
      return;
    }
    const script = document.createElement('script');
    script.src = 'https://unpkg.com/three@0.160.0/build/three.min.js';
    script.onload = () => callback(window.THREE);
    document.head.appendChild(script);
  }

  function createDotTexture(THREE) {
    const c = document.createElement('canvas');
    c.width = 64; c.height = 64;
    const ctx = c.getContext('2d');
    const grad = ctx.createRadialGradient(32, 32, 0, 32, 32, 32);
    grad.addColorStop(0, 'rgba(255, 255, 255, 1)');
    grad.addColorStop(0.25, 'rgba(235, 245, 255, 0.95)');
    grad.addColorStop(0.5, 'rgba(120, 195, 255, 0.45)');
    grad.addColorStop(0.8, 'rgba(42, 66, 247, 0.15)');
    grad.addColorStop(1, 'rgba(0, 0, 0, 0)');
    ctx.fillStyle = grad;
    ctx.fillRect(0, 0, 64, 64);
    return new THREE.CanvasTexture(c);
  }

  // 1. Starfield Engine
  function initStarfield(container, THREE) {
    const canvas = document.createElement('canvas');
    setupCanvasStyle(canvas, container);
    const scene = new THREE.Scene();
    let w = container.clientWidth || 800;
    let h = container.clientHeight || 500;
    const camera = new THREE.PerspectiveCamera(60, w / h, 0.1, 1000);
    camera.position.z = 250;

    const renderer = new THREE.WebGLRenderer({ canvas, alpha: true, antialias: true });
    renderer.setSize(w, h);
    renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));

    const count = 1000;
    const geo = new THREE.BufferGeometry();
    const pos = new Float32Array(count * 3);
    const col = new Float32Array(count * 3);
    const speeds = new Float32Array(count);
    const bounds = { xMin: -350, xMax: 350, yMin: -250, yMax: 250, zMin: -200, zMax: 150 };

    for (let i = 0; i < count; i++) {
      const i3 = i * 3;
      pos[i3] = THREE.MathUtils.randFloat(bounds.xMin, bounds.xMax);
      pos[i3+1] = THREE.MathUtils.randFloat(bounds.yMin, bounds.yMax);
      pos[i3+2] = THREE.MathUtils.randFloat(bounds.zMin, bounds.zMax);
      speeds[i] = 0.4 + 0.6 * ((pos[i3+2] - bounds.zMin) / 350);
      col[i3] = 0.85; col[i3+1] = 0.92; col[i3+2] = 1.0;
    }
    geo.setAttribute('position', new THREE.BufferAttribute(pos, 3));
    geo.setAttribute('color', new THREE.BufferAttribute(col, 3));

    const mat = new THREE.PointsMaterial({
      size: 4.5, map: createDotTexture(THREE), vertexColors: true,
      transparent: true, opacity: 0.9, blending: THREE.AdditiveBlending, depthWrite: false
    });
    scene.add(new THREE.Points(geo, mat));

    const clock = new THREE.Clock();
    let isRunning = true;
    function loop() {
      if (!isRunning) return;
      requestAnimationFrame(loop);
      const dt = Math.min(clock.getDelta(), 0.1);
      const p = geo.attributes.position.array;
      const drift = 12.0 * dt;
      for (let i = 0; i < count; i++) {
        const i3 = i * 3;
        p[i3] += 0.85 * speeds[i] * drift;
        p[i3+1] += 0.52 * speeds[i] * drift;
        if (p[i3] > bounds.xMax || p[i3+1] > bounds.yMax) {
          if (Math.random() > 0.5) { p[i3] = bounds.xMin; p[i3+1] = THREE.MathUtils.randFloat(bounds.yMin, bounds.yMax); }
          else { p[i3] = THREE.MathUtils.randFloat(bounds.xMin, bounds.xMax); p[i3+1] = bounds.yMin; }
        }
      }
      geo.attributes.position.needsUpdate = true;
      renderer.render(scene, camera);
    }
    loop();

    return setupObserver(container, camera, renderer, () => { isRunning = false; renderer.dispose(); canvas.remove(); });
  }

  // 2. Water Ripple Net Engine (Default / Most Popular)
  function initRippleNet(container, THREE, opts = {}) {
    const canvas = document.createElement('canvas');
    setupCanvasStyle(canvas, container);
    const scene = new THREE.Scene();
    let w = container.clientWidth || 800;
    let h = container.clientHeight || 500;
    const camera = new THREE.PerspectiveCamera(55, w / h, 0.1, 1000);
    camera.position.set(0, 0, 165);

    const renderer = new THREE.WebGLRenderer({ canvas, alpha: true, antialias: true });
    renderer.setSize(w, h);
    renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));

    const bounds = { x: 180, y: 110, z: 70 };
    const nodeCount = opts.nodeCount || 130;
    const waveSpeed = opts.waveSpeed || 36.0;
    const wavelength = opts.wavelength || 28.0;
    const hasLines = opts.hasLines !== false;

    const nodes = [];
    class Node {
      constructor(id) {
        this.id = id;
        this.basePos = new THREE.Vector3(
          THREE.MathUtils.randFloatSpread(bounds.x * 2),
          THREE.MathUtils.randFloatSpread(bounds.y * 2),
          THREE.MathUtils.randFloatSpread(bounds.z * 2)
        );
        this.renderPos = this.basePos.clone();
        this.vel = new THREE.Vector3(THREE.MathUtils.randFloatSpread(2.0), THREE.MathUtils.randFloatSpread(2.0), THREE.MathUtils.randFloatSpread(1.2));
        this.pulse = 0;
      }
      update(dt, ripples) {
        this.basePos.addScaledVector(this.vel, dt);
        ['x', 'y', 'z'].forEach(a => {
          if (this.basePos[a] > bounds[a]) { this.basePos[a] = bounds[a]; this.vel[a] *= -1; }
          else if (this.basePos[a] < -bounds[a]) { this.basePos[a] = -bounds[a]; this.vel[a] *= -1; }
        });
        let dispZ = 0, radX = 0, radY = 0, maxEx = 0;
        for (let r of ripples) {
          const dx = this.basePos.x - r.x; const dy = this.basePos.y - r.y;
          const d = Math.sqrt(dx*dx + dy*dy);
          const delta = d - r.radius;
          const span = wavelength * 1.5;
          if (Math.abs(delta) < span) {
            const phase = (delta / wavelength) * Math.PI * 2;
            const env = Math.max(0, 1 - Math.abs(delta) / span);
            const wave = Math.cos(phase) * env * r.intensity;
            dispZ += wave * 10.0;
            if (d > 0.1) { radX += (dx/d) * wave * 3.5; radY += (dy/d) * wave * 3.5; }
            if (wave > maxEx) maxEx = wave;
          }
        }
        this.renderPos.x = this.basePos.x + radX;
        this.renderPos.y = this.basePos.y + radY;
        this.renderPos.z = this.basePos.z + dispZ;
        if (maxEx > 0.05) this.pulse = Math.max(this.pulse, maxEx);
        else if (this.pulse > 0) this.pulse = Math.max(0, this.pulse - dt * 1.2);
      }
    }
    for (let i = 0; i < nodeCount; i++) nodes.push(new Node(i));

    const ripples = [];
    class Ripple {
      constructor(x, y) { this.x = x; this.y = y; this.radius = 0; this.age = 0; }
      update(dt) { this.age += dt; this.radius += waveSpeed * dt; }
      get active() { return this.age < 4.5; }
      get intensity() { const p = this.age / 4.5; return Math.max(0, (1 - p) * (1 - p)); }
    }
    function spawn(x, y) { ripples.push(new Ripple(x, y)); if (ripples.length > 6) ripples.shift(); }

    // Pointer events inside container
    const raycaster = new THREE.Raycaster();
    const mouseNdc = new THREE.Vector2(-999, -999);
    const planeZ = new THREE.Plane(new THREE.Vector3(0, 0, 1), 0);
    const mouse3D = new THREE.Vector3();
    let lastTime = 0, lastPos = new THREE.Vector2();

    function onPointerMove(e) {
      const rect = container.getBoundingClientRect();
      if (e.clientX < rect.left || e.clientX > rect.right || e.clientY < rect.top || e.clientY > rect.bottom) return;
      mouseNdc.x = ((e.clientX - rect.left) / rect.width) * 2 - 1;
      mouseNdc.y = -((e.clientY - rect.top) / rect.height) * 2 + 1;
      raycaster.setFromCamera(mouseNdc, camera);
      raycaster.ray.intersectPlane(planeZ, mouse3D);
      const now = performance.now();
      const cur = new THREE.Vector2(e.clientX, e.clientY);
      if (cur.distanceTo(lastPos) > 50 && now - lastTime > 400) {
        lastTime = now; lastPos.copy(cur);
        spawn(mouse3D.x, mouse3D.y);
      }
    }
    function onPointerDown(e) {
      const rect = container.getBoundingClientRect();
      if (e.clientX < rect.left || e.clientX > rect.right || e.clientY < rect.top || e.clientY > rect.bottom) return;
      mouseNdc.x = ((e.clientX - rect.left) / rect.width) * 2 - 1;
      mouseNdc.y = -((e.clientY - rect.top) / rect.height) * 2 + 1;
      raycaster.setFromCamera(mouseNdc, camera);
      raycaster.ray.intersectPlane(planeZ, mouse3D);
      spawn(mouse3D.x, mouse3D.y);
    }
    window.addEventListener('pointermove', onPointerMove, { passive: true });
    container.addEventListener('pointerdown', onPointerDown);

    // Points
    const nodeGeo = new THREE.BufferGeometry();
    const np = new Float32Array(nodeCount * 3);
    const nc = new Float32Array(nodeCount * 3);
    nodeGeo.setAttribute('position', new THREE.BufferAttribute(np, 3));
    nodeGeo.setAttribute('color', new THREE.BufferAttribute(nc, 3));
    const nodeMat = new THREE.PointsMaterial({
      size: 5.5, map: createDotTexture(THREE), vertexColors: true,
      transparent: true, opacity: 0.95, blending: THREE.AdditiveBlending, depthWrite: false
    });
    scene.add(new THREE.Points(nodeGeo, nodeMat));

    // Lines
    const maxLines = hasLines ? 900 : 0;
    const lineGeo = new THREE.BufferGeometry();
    const lp = new Float32Array(maxLines * 6);
    const lc = new Float32Array(maxLines * 6);
    if (hasLines) {
      lineGeo.setAttribute('position', new THREE.BufferAttribute(lp, 3));
      lineGeo.setAttribute('color', new THREE.BufferAttribute(lc, 3));
      const lineMat = new THREE.LineBasicMaterial({
        vertexColors: true, transparent: true, opacity: 0.8, blending: THREE.AdditiveBlending, depthWrite: false
      });
      scene.add(new THREE.LineSegments(lineGeo, lineMat));
    }

    const clock = new THREE.Clock();
    let idleTimer = 0, isRunning = true;
    function loop() {
      if (!isRunning) return;
      requestAnimationFrame(loop);
      const dt = Math.min(clock.getDelta(), 0.1);
      idleTimer += dt;
      if (idleTimer > 3.8) { idleTimer = 0; spawn(THREE.MathUtils.randFloatSpread(140), THREE.MathUtils.randFloatSpread(80)); }

      for (let i = ripples.length - 1; i >= 0; i--) {
        ripples[i].update(dt);
        if (!ripples[i].active) ripples.splice(i, 1);
      }

      const pArr = nodeGeo.attributes.position.array;
      const cArr = nodeGeo.attributes.color.array;
      for (let i = 0; i < nodeCount; i++) {
        const n = nodes[i];
        n.update(dt, ripples);
        const i3 = i * 3;
        pArr[i3] = n.renderPos.x; pArr[i3+1] = n.renderPos.y; pArr[i3+2] = n.renderPos.z;
        if (n.pulse > 0.05) {
          cArr[i3] = 0.5 + 0.5 * n.pulse; cArr[i3+1] = 0.8 + 0.2 * n.pulse; cArr[i3+2] = 1.0;
        } else {
          cArr[i3] = 0.40; cArr[i3+1] = 0.65; cArr[i3+2] = 1.0;
        }
      }
      nodeGeo.attributes.position.needsUpdate = true;
      nodeGeo.attributes.color.needsUpdate = true;

      if (hasLines) {
        const lPos = lineGeo.attributes.position.array;
        const lCol = lineGeo.attributes.color.array;
        let lineCount = 0;
        for (let i = 0; i < nodeCount; i++) {
          const a = nodes[i];
          let conns = 0;
          for (let j = i + 1; j < nodeCount; j++) {
            if (conns >= 4) break;
            const b = nodes[j];
            const dist = a.renderPos.distanceTo(b.renderPos);
            if (dist < 42 && lineCount < maxLines) {
              conns++;
              const idx = lineCount * 6;
              lPos[idx] = a.renderPos.x; lPos[idx+1] = a.renderPos.y; lPos[idx+2] = a.renderPos.z;
              lPos[idx+3] = b.renderPos.x; lPos[idx+4] = b.renderPos.y; lPos[idx+5] = b.renderPos.z;
              const alpha = Math.max(0.08, 1 - dist / 42);
              const p = Math.max(a.pulse, b.pulse);
              lCol[idx] = 0.18 + 0.75 * p; lCol[idx+1] = (0.42 + 0.55 * p) * alpha; lCol[idx+2] = alpha;
              lCol[idx+3] = 0.18 + 0.75 * p; lCol[idx+4] = (0.42 + 0.55 * p) * alpha; lCol[idx+5] = alpha;
              lineCount++;
            }
          }
        }
        lineGeo.setDrawRange(0, lineCount * 2);
        lineGeo.attributes.position.needsUpdate = true;
        lineGeo.attributes.color.needsUpdate = true;
      }
      renderer.render(scene, camera);
    }
    loop();

    return setupObserver(container, camera, renderer, () => {
      isRunning = false;
      window.removeEventListener('pointermove', onPointerMove);
      container.removeEventListener('pointerdown', onPointerDown);
      renderer.dispose();
      canvas.remove();
    });
  }

  // Helper: auto canvas style
  function setupCanvasStyle(canvas, container) {
    if (window.getComputedStyle(container).position === 'static') {
      container.style.position = 'relative';
    }
    canvas.style.position = 'absolute';
    canvas.style.top = '0';
    canvas.style.left = '0';
    canvas.style.width = '100%';
    canvas.style.height = '100%';
    canvas.style.zIndex = '1';
    canvas.style.pointerEvents = 'none';
    container.prepend(canvas);
  }

  // Helper: setup ResizeObserver
  function setupObserver(container, camera, renderer, onDestroy) {
    const ro = new ResizeObserver(() => {
      const w = container.clientWidth || 300;
      const h = container.clientHeight || 200;
      camera.aspect = w / h;
      camera.updateProjectionMatrix();
      renderer.setSize(w, h);
    });
    ro.observe(container);

    return {
      destroy: () => {
        ro.disconnect();
        onDestroy();
      }
    };
  }

  // Public Library API
  const SynapticNet = {
    init: function (selectorOrEl, effectName = 'ripple-net', options = {}) {
      const el = typeof selectorOrEl === 'string' ? document.querySelector(selectorOrEl) : selectorOrEl;
      if (!el) {
        console.warn('[SynapticNet] Target element not found:', selectorOrEl);
        return null;
      }
      loadThree(THREE => {
        if (effectName === 'starfield') {
          initStarfield(el, THREE);
        } else if (effectName === 'dots-only') {
          initRippleNet(el, THREE, { hasLines: false, nodeCount: 160, ...options });
        } else {
          // Default: ripple-net (Demo 5)
          initRippleNet(el, THREE, options);
        }
      });
    },

    // Auto-detect any element with [data-synaptic-bg]
    autoInit: function () {
      loadThree(THREE => {
        document.querySelectorAll('[data-synaptic-bg]').forEach(el => {
          const effect = el.getAttribute('data-synaptic-bg') || 'ripple-net';
          if (effect === 'starfield') initStarfield(el, THREE);
          else if (effect === 'dots-only') initRippleNet(el, THREE, { hasLines: false, nodeCount: 160 });
          else initRippleNet(el, THREE);
        });
      });
    }
  };

  window.SynapticNet = SynapticNet;

  // Run automatically when the DOM is ready
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', SynapticNet.autoInit);
  } else {
    SynapticNet.autoInit();
  }
})();